import React, { useState, useEffect, useContext } from 'react'
import { Row, Col, Checkbox, TreeSelect, Spin } from 'antd'
import { DependencyArrayStyleContainer } from './index.style'
import { store } from './store'
import { get } from 'lodash'

const { TreeNode } = TreeSelect
function childNode (data) {
  if (data && data.length > 0) {
    return data.map((item, index) => {
      if (item.nested.length === 0) {
        const data = (
          <div>
            <span>{item.name}</span> <br />
          </div>
        )
        return (
          <TreeNode value={item.id} title={data} />
        )
      } else {
        return (
          <TreeNode title={item.name}>
            {childNode(item.nested)}
          </TreeNode>
        )
      }
    })
  }
}

function checkParentAttributes (data, attributesArray = []) {
  if (data && data.length > 0) {
    data.forEach((item) => {
      if (item.nested.length > 0) {
        attributesArray.push(item.id)
        checkParentAttributes(item.nested, attributesArray)
      }
    })
  }
  return attributesArray
}

export default function DependencyArray (props) {
  const {
    // localAttributes,
    // validationData,
    // updatedData,
    // intialData,
    attributesData,
    formNameCode,
    formNameId
  } = props
  const currentFormKey = `${formNameCode}-${formNameId}`
  const { state, dispatch } = useContext(store)
  const [isLoading, setLoading] = useState(true)
  const [validationLocal, setValidation] = useState([])
  const [showParentdependency, setParentDependency] = useState(true)

  useEffect(() => {
    if (get(state, currentFormKey, []).length > 0) {
      setLoading(false)
      const notChildAttribute = checkParentAttributes(attributesData) || []

      if (notChildAttribute.length > 0 && notChildAttribute.includes(formNameId)) {
        setParentDependency(false)
      }
      setValidation(state[currentFormKey])
    }
  }, [state])

  // useEffect(() => {
  //   if (intialData.length > 0) {
  //     setLoading(false)
  //     let newValidation = []
  //     if (formNameCode && formNameId) {
  //       const selectedAttribute = (intialData.find(item => item.product_attribute_code === formNameCode) || {})
  //       const validations = size(selectedAttribute) > 0 ? selectedAttribute.validations : []
  //       if (validations.length === 0) {
  //         newValidation = [{
  //           '_id': 1,
  //           'id': null,
  //           'value': null,
  //           'is_dependent_validation': false,
  //           'dependent_validation_product_attribute_id': null,
  //           'select_field': false
  //         }]
  //       } else {
  //         newValidation = validations.map((item, index) => {
  //           return {
  //             ...item,
  //             '_id': index + 1,
  //             'select_field': item.is_dependent_validation,
  //             'is_dependent_validation': item.is_dependent_validation ? item.is_dependent_validation : false,
  //             'dependent_validation_product_attribute_id': item.dependent_validation_product_attribute_id ? item.dependent_validation_product_attribute_id : null
  //           }
  //         })
  //       }
  //       setValidation(newValidation)
  //     }
  //   }
  // }, [intialData])

  function updateLocalStorage (validations) {
    const data = {
      product_attribute_id: formNameId,
      validations: validations.map(item => {
        return {
          custom_message: item.custom_message,
          dependent_validation_product_attribute_id: item.dependent_validation_product_attribute_id,
          id: item.validationCode,
          is_dependent_validation: item.is_dependent_validation,
          value: item.multipleSelectData
        }
      })
    }
    window.sessionStorage.setItem(`${formNameCode}-${formNameId}`, JSON.stringify(data))
    // updatedData(data)
  }

  function onChange (e, formNameCode, id) {
    const validations = validationLocal.map(item => {
      if (item.id === id) {
        return {
          ...item,
          is_dependent_validation: e.target.checked,
          dependent_validation_product_attribute_id: e.target.checked === false ? null : item.dependent_validation_product_attribute_id
        }
      }
      return item
    })
    updateLocalStorage(validations)
    dispatch({
      type: 'add-validation',
      payload: {
        keyName: currentFormKey,
        keyData: validations
      }
    }
    )
  }

  function onChangeSelectField (value, label, extra, formNameCode, id) {
    const validations = validationLocal.map(item => {
      if (item.id === id) {
        return {
          ...item,
          dependent_validation_product_attribute_id: value
        }
      }
      return item
    })
    updateLocalStorage(validations)
    dispatch({
      type: 'add-validation',
      payload: {
        keyName: currentFormKey,
        keyData: validations
      }
    }
    )
  }

  if (showParentdependency) {
    return validationLocal.map((item, index) => {
      return (
        <DependencyArrayStyleContainer key={item.id}>
          <Spin spinning={isLoading}>
            <Row type='flex' justify='space-between' align='middle' className='single-validation-row'>
              <Col>
                <Checkbox disabled={item.id === null} checked={item.is_dependent_validation} onChange={(e) => onChange(e, formNameCode, item.id)} />
              </Col>
              <Col span={18}>
                <TreeSelect
                  disabled={!item.is_dependent_validation}
                  value={item.dependent_validation_product_attribute_id}
                  // className={''}
                  // placeholder={''}
                  onChange={(value, label, extra) => onChangeSelectField(value, label, extra, formNameCode, item.id)}
                  treeDefaultExpandAll
                >
                  {
                    childNode(attributesData)
                  }
                </TreeSelect>
              </Col>
            </Row>
          </Spin>
        </DependencyArrayStyleContainer>
      )
    })
  } else {
    return '-'
  }
}
