/* eslint-disable react-hooks/exhaustive-deps */
import React, { useState, useRef, useEffect, useContext } from 'react'
import PropTypes from 'prop-types'
import { get, size } from 'lodash'
import Formitem from './formItem'
import { localStorageCheck } from '../../../../../util/localstorageCheck'
import { initialValueMapper } from '../../AttributesValidationSection/commanFunction'
import { store } from './store'
export default function ValidationField (props) {
  const { validationData, intialData, formNameCode, formNameId, packageName } = props
  const currentFormKey = `${formNameCode}-${formNameId}`
  const { state, dispatch } = useContext(store)
  const [validationDataState, setValidationData] = useState([])
  const [initialFormState, setInitialForm] = useState([])
  const [intialDataState, setIntialData] = useState([])
  //  THis behaviour will use for component will mount
  const willMount = useRef(true)

  if (willMount.current) {
    if (formNameCode && formNameId) {
      const data = {
        product_attribute_id: formNameId,
        validations: []
      }
      window.sessionStorage.setItem(`${formNameCode}-${formNameId}`, JSON.stringify(data))
    }
    willMount.current = false
  }

  useEffect(() => {
    if (validationDataState.length === 0) {
      setValidationData(validationData)
      if (validationData.length > 0) {
        if (formNameCode === 'reference_id') {
          const selectedData = validationData.find(item => item.code === 'required') || {}
          const referenceId = selectedData.id
          const data = {
            product_attribute_id: formNameId,
            validations: [
              {
                id: referenceId,
                value: null,
                is_dependent_validation: selectedData.is_dependent_validation,
                dependent_validation_product_attribute_id: selectedData.dependent_validation_product_attribute_id,
                custom_messages: selectedData.custom_messages ? selectedData.custom_messages : []
              }
            ]
          }
          window.sessionStorage.setItem(`${formNameCode}-${formNameId}`, JSON.stringify(data))
        }
        if (formNameCode === 'package_id') {
          const selectedPackageData = validationData.find(item => item.code === 'required') || {}
          const pacakageIdRequired = selectedPackageData.id
          const selectedValidationData = validationData.find(item => item.code === 'oneof') || {}
          const oneOfId = selectedValidationData.id
          const data = {
            product_attribute_id: formNameId,
            validations: [
              {
                id: pacakageIdRequired,
                value: null,
                is_dependent_validation: selectedPackageData.is_dependent_validation,
                dependent_validation_product_attribute_id: selectedPackageData.dependent_validation_product_attribute_id,
                custom_messages: selectedPackageData.custom_messages ? selectedPackageData.custom_messages : []
              },
              {
                id: oneOfId,
                value: packageName,
                is_dependent_validation: selectedValidationData.is_dependent_validation,
                dependent_validation_product_attribute_id: selectedValidationData.dependent_validation_product_attribute_id,
                custom_messages: selectedValidationData.custom_messages ? selectedValidationData.custom_messages : []

              }
            ]
          }
          window.sessionStorage.setItem(`${formNameCode}-${formNameId}`, JSON.stringify(data))
        }
      }
    }

    if (size(intialDataState) === 0) {
      setIntialData(intialData)
      const localStorageData = JSON.parse(window.sessionStorage.getItem(`${formNameCode}-${formNameId}`)) || {}
      if (size(localStorageData) > 0) {
        setFieldValue(initialValueMapper(intialData, localStorageData), validationDataState)
      }
    }
    if (size(intialDataState) === 0 && size(intialData) === 0) {
      setFieldValue({}, validationDataState)
    }
  }, [validationData, intialData, formNameCode, packageName])

  useEffect(() => {
    return () => {
      if (formNameCode && formNameId) {
        window.sessionStorage.removeItem(`${formNameCode}-${formNameId}`)
      }
    }
  }, [])

  useEffect(() => {
    if (state[currentFormKey]) {
      setInitialForm(state[currentFormKey])
    }
  }, [state])

  const setFieldValue = (editInitialData = {}, validationData) => {
    const dataValidation = window.sessionStorage.getItem(`${formNameCode}-${formNameId}`)
    const dataValidationObject = size(editInitialData) > 0 ? editInitialData : localStorageCheck(dataValidation)
    if (size(dataValidationObject) > 0) {
      const validationsArray = get(dataValidationObject, 'validations', [])
      if (validationsArray.length > 0) {
        const formFieldData = []

        validationsArray.forEach((item, index) => {
          let validationObject = {}
          if (validationData.length > 0) {
            validationObject = validationData.find(k => k.code === item.code) || {}
          }
          const validationitem = validationObject.code || ''
          const data = {
            id: index + 1,
            attributeId: null,
            showAddButton: false,
            deleteButton: true,
            showMultiSelect: item.value !== '' ? item.value : false,
            validationCode: item.id,
            validationName: validationitem,
            multipleSelectData: item.value,
            is_dependent_validation: item.is_dependent_validation,
            dependent_validation_product_attribute_id: item.dependent_validation_product_attribute_id,
            custom_message: item.custom_message ? item.custom_message : []
          }
          formFieldData.push(data)
        })
        if (formFieldData.length === 1) {
          formFieldData[0].deleteButton = false
        }
        formFieldData[formFieldData.length - 1].showAddButton = true
        dispatch({
          type: 'add-validation',
          payload: {
            keyName: currentFormKey,
            keyData: formFieldData
          }
        }
        )
        const data = JSON.parse(window.sessionStorage.getItem(`${formNameCode}-${formNameId}`))
        const validationsData = formFieldData.map((item, index) => {
          const object = {
            id: item.validationCode ? Number(item.validationCode) : index,
            value: item.multipleSelectData || null,
            is_dependent_validation: item.is_dependent_validation,
            dependent_validation_product_attribute_id: item.dependent_validation_product_attribute_id,
            custom_message: item.custom_message ? item.custom_message : []

          }
          return object
        })
        data.validations = validationsData
        window.sessionStorage.setItem(`${formNameCode}-${formNameId}`, JSON.stringify(data))
      } else {
        const data = {
          id: 1,
          attributeId: null,
          showAddButton: true,
          deleteButton: false,
          showMultiSelect: false,
          validationCode: '',
          validationName: '',
          multipleSelectData: null,
          is_dependent_validation: false,
          dependent_validation_product_attribute_id: null,
          custom_message: []
        }
        dispatch({
          type: 'add-validation',
          payload: {
            keyName: currentFormKey,
            keyData: [data]
          }
        }
        )
      }
    }
  }

  const remove = k => {
    let initialFormData = [...initialFormState]
    initialFormData = initialFormData.filter((item, index) => item.id !== k)
    if (initialFormData.length > 0) {
      initialFormData[initialFormData.length - 1].showAddButton = true
    }
    dispatch({
      type: 'add-validation',
      payload: {
        keyName: currentFormKey,
        keyData: initialFormData
      }
    }
    )
    if (initialFormData.length === 1) {
      const firstEntry = initialFormData.map(item => {
        return {
          ...item,
          showAddButton: true,
          deleteButton: false
        }
      })
      dispatch({
        type: 'add-validation',
        payload: {
          keyName: currentFormKey,
          keyData: firstEntry
        }
      }
      )
    }
    addingLocalStorage(initialFormData)
  }

  const add = () => {
    const prevData = initialFormState.map(item => {
      item.showAddButton = false
      item.deleteButton = true
      return item
    })
    const index = initialFormState[initialFormState.length - 1].id + 1
    dispatch({
      type: 'add-validation',
      payload: {
        keyName: currentFormKey,
        keyData: [...prevData, {
          id: index,
          showAddButton: true,
          deleteButton: true,
          showMultiSelect: false,
          validationCode: '',
          validationName: '',
          multipleSelectData: null,
          is_dependent_validation: false,
          dependent_validation_product_attribute_id: null
        }]
      }
    }
    )
    addingLocalStorage(initialFormState)
  }

  const addingLocalStorage = (initialFormData) => {
    let data = JSON.parse(window.sessionStorage.getItem(`${formNameCode}-${formNameId}`))
    const validationsData = initialFormData.map((item, index) => {
      const object = {
        id: item.validationCode ? Number(item.validationCode) : index,
        value: get(item, 'multipleSelectData', null),
        is_dependent_validation: item.is_dependent_validation,
        dependent_validation_product_attribute_id: item.dependent_validation_product_attribute_id,
        custom_message: item.custom_message ? item.custom_message : []
      }
      return object
    })
    data = {
      ...data,
      validations: validationsData
    }
    window.sessionStorage.setItem(`${formNameCode}-${formNameId}`, JSON.stringify(data))
  }

  const dynamicValuesHandler = (value, fieldIndex) => {
    const initialFormData = [...initialFormState]
    initialFormData.forEach((item, index) => {
      if (item.id === fieldIndex) {
        item.multipleSelectData = value.join(' ')
      }
    })
    dispatch({
      type: 'add-validation',
      payload: {
        keyName: currentFormKey,
        keyData: initialFormData
      }
    }
    )
    addingLocalStorage(initialFormData)
  }

  const selectHandler = (selectedOptionId, fieldIndex) => {
    const validationName = validationDataState.filter(item => item.id === Number(selectedOptionId))[0].name
    const dynamicCheck = validationDataState.filter(item => item.id === Number(selectedOptionId))[0].is_dynamic_value_required
    const initialFormData = [...initialFormState]

    initialFormData.forEach((item, index) => {
      if (item.id === fieldIndex) {
        item.multipleSelectData = dynamicCheck ? [] : null
        item.showMultiSelect = dynamicCheck
        item.validationCode = Number(selectedOptionId)
        item.validationName = validationName
      }
    })
    dispatch({
      type: 'add-validation',
      payload: {
        keyName: currentFormKey,
        keyData: initialFormData
      }
    }
    )
    addingLocalStorage(initialFormData)
  }

  return (
    <>
      {
        initialFormState.length > 0 &&
        validationDataState.length > 0 &&
          <Formitem
            data={initialFormState}
            add={add}
            remove={remove}
            dynamicValuesHandler={dynamicValuesHandler}
            selectHandler={selectHandler}
            validationData={validationDataState}
            formNameCode={formNameCode}
          />
      }
    </>
  )
}

ValidationField.defaultProps = {
  validationData: [],
  productValidationError: false,
  productValidationLoading: false
}
ValidationField.propTypes = {
  formNameCode: PropTypes.string,
  formNameId: PropTypes.number,
  index: PropTypes.number,
  validationData: PropTypes.array,
  productValidationError: PropTypes.bool,
  productValidationLoading: PropTypes.bool
}
