/* eslint-disable react-hooks/exhaustive-deps */
import { Input } from 'antd'
import React, { useContext, useEffect, useState } from 'react'
import { store } from './store'
import { get } from 'lodash'

export default function CustomeErrorMessageComponent ({ intialData, formNameCode, formNameId }) {
  const { state } = useContext(store)
  const currentFormKey = `${formNameCode}-${formNameId}`
  const [rowData, setRowData] = useState([])

  useEffect(() => {
    if (state[currentFormKey]) {
      setRowData(state[currentFormKey])
    }
  }, [state])
  return (
    <>
      {
        rowData.map((item, index) => {
          return (
            <InputComponent
              key={index}
              parentData={rowData}
              contentId={item.id}
              formKey={currentFormKey}
              defaultValue={get(item, 'custom_message[0].value', '')}
            />
          )
        })
      }
    </>
  )
}

export function InputComponent ({ parentData, formKey, contentId, defaultValue = '' }) {
  const [initialState, setInitialState] = useState(defaultValue)
  const { dispatch } = useContext(store)

  const handleChangeInput = (e) => {
    setInitialState(e.target.value)
    const payload = parentData.map((item) => {
      if (item.id === contentId) {
        return {
          ...item,
          custom_message: [
            {
              locale: 'en',
              value: e.target.value
            }
          ]
        }
      }
      return item
    })
    dispatch({
      type: 'add-validation',
      payload: {
        keyName: formKey,
        keyData: payload
      }
    })
    const originalData = JSON.parse(window.sessionStorage.getItem(formKey))
    const attributeData = {
      ...originalData,
      validations: payload.map((item) => {
        return {
          custom_message: item.custom_message,
          dependent_validation_product_attribute_id: item.dependent_validation_product_attribute_id,
          id: item.validationCode,
          is_dependent_validation: item.is_dependent_validation,
          value: item.multipleSelectData
        }
      })
    }
    window.sessionStorage.setItem(formKey, JSON.stringify(attributeData))
  }
  return (
    <Input
      value={initialState}
      onChange={handleChangeInput}
    />
  )
}
