/* eslint-disable react-hooks/exhaustive-deps */
import React, { useEffect, useState } from 'react'
import PropTypes from 'prop-types'
import CustomeErrorMessageComponent from './CustomErrorMessageComponent'
import DataValidationStyleWrapper, { ValidationTable } from './index.style'
import DataValidationField from './validationField'
import DependencyArray from './dependencyArray'
import { size } from 'lodash'

// import { Tree, Icon } from 'antd'
// const { TreeNode } = Tree
export default function DataValidation (props) {
  const [validationDataState, setValidationData] = useState([])
  const [intialDataState, setIntialData] = useState([])
  const [packageNameState, setPackageName] = useState('')
  const [stateProductAttributes, setProductAttributes] = useState([])
  const { validationData, intialData, packageName, productAttributes } = props

  useEffect(() => {
    if (packageNameState === '' && packageName !== '') {
      setPackageName(packageName)
    }
    if (size(validationData) > 0) {
      setValidationData(validationData)
    }
    if (size(intialData) > 0) {
      setIntialData(intialData)
    }
    if (productAttributes.length > 0 && stateProductAttributes.length === 0) {
      setProductAttributes(productAttributes)
    }
  }, [validationData, intialData, packageName, productAttributes])

  useEffect(() => {
    const { validationData, intialData, packageName } = props
    setPackageName(packageName)
    setValidationData(validationData)
    setIntialData(intialData)
  }, [])

  const {
    localAttributes = [],
    parentName = '',
    attributesData
  } = props
  const dataAttributes = size(localAttributes) === 0 ? stateProductAttributes : localAttributes
  return (
    <DataValidationStyleWrapper>
      <ValidationTable>
        <table className='table-style'>
          <thead>
            <tr>
              <th><b>Field Code {parentName ? `(${parentName})` : ''}</b></th>
              <th><b>Validation</b></th>
              <th><b>Dependency</b></th>
              <th><b>Custom Error Message</b></th>
            </tr>
          </thead>
          <tbody>
            {
              stateProductAttributes.length > 0 &&
              stateProductAttributes.map((item, index) => {
                return (
                  <React.Fragment key={index}>
                    <tr>
                      <td>{item.name}</td>
                      <td>
                        <DataValidationField
                          index={index}
                          formNameId={item.id}
                          formNameCode={item.code}
                          validationData={validationDataState}
                          intialData={intialDataState}
                          packageName={packageNameState}
                          // updatedData={updateValidation}
                          localAttributes={dataAttributes}
                          attributesData={attributesData}
                        />
                      </td>
                      <td>
                        <DependencyArray
                          // attributes={productAttributes}
                          index={index}
                          formNameId={item.id}
                          formNameCode={item.code}
                          validationData={validationDataState}
                          intialData={intialDataState}
                          packageName={packageNameState}
                          // updatedData={updateValidation}
                          localAttributes={dataAttributes}
                          attributesData={attributesData}
                        />
                      </td>
                      <td>
                        <CustomeErrorMessageComponent
                          formNameId={item.id}
                          formNameCode={item.code}
                          intialData={intialDataState}
                        />
                      </td>
                    </tr>
                    <tr>
                      <td colSpan={4}>
                        {
                          item.nested.length > 0 &&
                            <DataValidation
                              parentName={item.name}
                              productAttributes={item.nested}
                              validationData={validationDataState}
                              intialData={intialDataState}
                              packageName={packageNameState}
                              // updatedData={updateValidation}
                              localAttributes={dataAttributes}
                              attributesData={attributesData}
                            />
                        }
                      </td>
                    </tr>
                  </React.Fragment>
                )
              })
            }
          </tbody>
        </table>
      </ValidationTable>
    </DataValidationStyleWrapper>
  )
}
DataValidation.defaultProps = {
  intialData: [],
  productAttributes: [],
  validationData: []
}
DataValidation.propTypes = {
  intialData: PropTypes.arrayOf(PropTypes.object),
  productAttributes: PropTypes.array,
  validationData: PropTypes.arrayOf(PropTypes.object)
}
