import { size, get } from 'lodash'

export const localstorageCheck = (code) => {
  const data = JSON.parse(window.sessionStorage.getItem(code))
  const dataCheck = size(data) > 0
  if (dataCheck) {
    return true
  }
}

export const initialValueMapper = (apiResponse = [], localStorageData = {}) => {
  const editValidationItem = apiResponse.find(item => item.product_attribute_id === localStorageData.product_attribute_id)
  if (editValidationItem) {
    localStorageData.validations = get(editValidationItem, 'validations', []).map((item) => {
      return {
        id: item.validation_id ? item.validation_id : item.id,
        value: item.value,
        code: item.code,
        is_dependent_validation: item.is_dependent_validation,
        dependent_validation_product_attribute_id: item.dependent_validation_product_attribute_id,
        custom_message: item.custom_message ? item.custom_message : []
      }
    })
    window.sessionStorage.setItem(`${editValidationItem.product_attribute_code}-${editValidationItem.product_attribute_id}`, JSON.stringify(localStorageData))
    return localStorageData
  }
}

export const traceValidation = (data) => {
  const newData = []
  let validationLength = 0
  function traverse (data) {
    data.forEach(item => {
      if (item.nested.length === 0) {
        const attributeCode = item.code
        const attributeId = item.id
        const findValidationCheck = localstorageCheck(`${attributeCode}-${attributeId}`)
        if (findValidationCheck) {
          validationLength++
          const localData = JSON.parse(window.sessionStorage.getItem(`${attributeCode}-${attributeId}`))
          if (get(localData, 'validations', []).length > 0) {
            const validationData = get(localData, 'validations').map(item => {
              return {
                id: get(item, 'id'),
                value: Array.isArray(get(item, 'value')) ? null : get(item, 'value'),
                is_dependent_validation: get(item, 'is_dependent_validation'),
                dependent_validation_product_attribute_id: get(item, 'dependent_validation_product_attribute_id'),
                custom_message: get(item, 'custom_message')
              }
            })
            newData.push({
              ...localData,
              validations: validationData
            })
          } else {
            newData.push(localData)
          }
          window.sessionStorage.removeItem(`${attributeCode}-${attributeId}`)
        }
      } else {
        const attributeCode = item.code
        const attributeId = item.id
        const findValidationCheck = localstorageCheck(`${attributeCode}-${attributeId}`)
        if (findValidationCheck) {
          validationLength++
          const localData = JSON.parse(window.sessionStorage.getItem(`${attributeCode}-${attributeId}`))
          if (get(localData, 'validations', []).length > 0) {
            const validationData = get(localData, 'validations').map(item => {
              return {
                id: get(item, 'id'),
                value: Array.isArray(get(item, 'value')) ? null : get(item, 'value'),
                is_dependent_validation: get(item, 'is_dependent_validation'),
                dependent_validation_product_attribute_id: get(item, 'dependent_validation_product_attribute_id'),
                custom_message: get(item, 'custom_message')
              }
            })
            newData.push({
              ...localData,
              validations: validationData
            })
          } else {
            newData.push(localData)
          }
          window.sessionStorage.removeItem(`${attributeCode}-${attributeId}`)
        }
        traverse(item.nested)
      }
    })
  }
  traverse(data)
  return {
    data: newData,
    validationLength: validationLength
  }
}
