import React from 'react'
import { Row, Select, Col, Icon } from 'antd'
const { Option } = Select

export default function FormItem (props) {
  const {
    data,
    validationData,
    formNameCode
  } = props
  const children = []
  return data.map((item, index) => {
    let validationObject = {}
    if (validationData.length > 0) {
      validationObject = validationData.find(k => k.id === item.validationCode) || {}
    }
    const multipleSelectedData = item.multipleSelectData !== null && (item.multipleSelectData.length > 0 ? item.multipleSelectData.split(' ') : [])
    const selectedTags = multipleSelectedData
    const validationName = validationObject.name
    const disbledCheck = formNameCode === 'package_id' || formNameCode === 'reference_id'
    return (
      <Row type='flex' justify='space-between' align='middle' key={item.id} className='single-validation-row'>
        <Col span={8}>
          <Select
            showSearch
            disabled={disbledCheck}
            value={validationName}
            className='validation-field validation'
            onChange={(e) => props.selectHandler(e, item.id)}
            placeholder='Select Validation'
            filterOption={(input, option) =>
              option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0
            }
          >
            {
              validationData.map(item2 => (<Option className='option-overflow' value={item2.id} key={item2.id}>{item2.name}</Option>))
            }
          </Select>
        </Col>
        {
          item.showMultiSelect &&
          <Col span={8}>
            <Select
              disabled={disbledCheck}
              value={selectedTags}
              className='validation-field edit-validation'
              mode='tags'
              placeholder='Validation Values'
              onChange={(e) => props.dynamicValuesHandler(e, item.id)}
            >
              { children }
            </Select>
          </Col>
        }
        <Col className='action-buttons' >
          <div className='icon-div'>
            {
              !disbledCheck &&
              item.showAddButton &&
              <Icon
                className='dynamic-add-button button-size'
                type='plus-circle'
                theme='filled'
                onClick={props.add}
              />
            }
            {
              !disbledCheck &&
              item.deleteButton &&
              <Icon
                style={{ marginLeft: 5 }}
                className='dynamic-delete-button button-size'
                type='minus-circle'
                theme='filled'
                onClick={() => props.remove(item.id)}
              />
            }
          </div>
        </Col>
      </Row>
    )
  })
}
